     1	import java.util.ArrayList;
     2	import java.util.List;
     3	
     4	class RodCuttingSolver implements Solver {
     5	
     6	    private static class BestCut {
     7	        final int length;
     8	        final int revenue;
     9	
    10	        BestCut(int length, int revenue) {
    11	            this.length = length;
    12	            this.revenue = revenue;
    13	        }
    14	    }
    15	
    16	    private static class RevenueTable {
    17	        private final int[] values;
    18	
    19	        RevenueTable(int size) {
    20	            this.values = new int[size];
    21	        }
    22	
    23	        int revenueFor(int length) {
    24	            return values[length];
    25	        }
    26	
    27	        void set(int length, int revenue) {
    28	            values[length] = revenue;
    29	        }
    30	    }
    31	
    32	    private static class CutChoiceTable {
    33	        private final int[] values;
    34	
    35	        CutChoiceTable(int size) {
    36	            this.values = new int[size];
    37	        }
    38	
    39	        int cutFor(int length) {
    40	            return values[length];
    41	        }
    42	
    43	        void set(int length, int cut) {
    44	            values[length] = cut;
    45	        }
    46	    }
    47	
    48	    @Override
    49	    public RodCuttingSolution solve(RodCuttingProblem problem) {
    50	        int n = problem.rodLength();
    51	        PriceTable prices = problem.prices();
    52	        RevenueTable revenue = new RevenueTable(n + 1);
    53	        CutChoiceTable cutChoice = new CutChoiceTable(n + 1);
    54	
    55	        for (int i = 1; i <= n; i++) {
    56	            BestCut best = findBestCut(i, prices, revenue);
    57	            revenue.set(i, best.revenue);
    58	            cutChoice.set(i, best.length);
    59	        }
    60	
    61	        return new RodCuttingSolution(revenue.revenueFor(n), reconstructCuts(n, cutChoice));
    62	    }
    63	
    64	    private BestCut findBestCut(int rodLength, PriceTable prices, RevenueTable revenue) {
    65	        int bestRevenue = Integer.MIN_VALUE;
    66	        int bestCutLength = -1;
    67	
    68	        for (int cutLength = 1; cutLength <= rodLength; cutLength++) {
    69	            int candidate = prices.priceFor(cutLength) + revenue.revenueFor(rodLength - cutLength);
    70	            if (candidate > bestRevenue) {
    71	                bestRevenue = candidate;
    72	                bestCutLength = cutLength;
    73	            }
    74	        }
    75	
    76	        return new BestCut(bestCutLength, bestRevenue);
    77	    }
    78	
    79	    private List<Integer> reconstructCuts(int n, CutChoiceTable cutChoice) {
    80	        List<Integer> cuts = new ArrayList<>();
    81	        int remaining = n;
    82	        while (remaining > 0) {
    83	            int cut = cutChoice.cutFor(remaining);
    84	            cuts.add(cut);
    85	            remaining -= cut;
    86	        }
    87	        return cuts;
    88	    }
    89	}

